    if ((a == NULL) || (b == NULL) || (distance_rad == NULL)) {
        return ADCS_E_NULL;
    }

    adcs_quat_t norm_a, norm_b;
    if (adcs_quat_normalize(a, &norm_a) != ADCS_OK) {
        *distance_rad = INFINITY;
        return ADCS_E_DEGENERATE;
    }
    if (adcs_quat_normalize(b, &norm_b) != ADCS_OK) {
        *distance_rad = INFINITY;
        return ADCS_E_DEGENERATE;
    }

    adcs_quat_t q_a_conj = adcs_quat_conjugate(&norm_a);
    adcs_quat_t q_rel = adcs_quat_multiply(&norm_b, &q_a_conj);

    double abs_w = fabs(q_rel.w);
    double clamped_w = ADCS_CLAMP(abs_w, 0.0, 1.0);

    *distance_rad = 2.0 * acos(clamped_w);

    return ADCS_OK;
}

